fn dispatch(model:&mut Model<'_>,b:&a::Binding,ticket:&super::Ticket,refused:&mut usize,player:&mut Vec<(u32,u32,usize)>,fire:&mut Vec<(u32,usize)>)->super::Frame{let e=ticket.event;let before=model.clock(b,b.observed).unwrap();let input=match e.kind{
 Kind::PlayerStart|Kind::PlayerAdvance=>{let mut bad=fixture::inputs();bad.all_layer_pointers_present=None;assert!(model.dispatch(b,b.observed,ticket,Inputs::Player(bad),&draw()).is_err());let mut skipped=fixture::inputs();skipped.actor_flags=Some(2);assert!(model.dispatch(b,b.observed,ticket,Inputs::Player(skipped),&draw()).is_err());*refused+=2;Inputs::Player(fixture::inputs())},
 Kind::PlayerIdle=>{let mut bad=idle_input(e.at);bad.scheduler_sample_ms=None;assert!(model.dispatch(b,b.observed,ticket,Inputs::Idle{callback:bad,draw:fixture::inputs()},&draw()).is_err());*refused+=1;Inputs::Idle{callback:idle_input(e.at),draw:fixture::inputs()}},
 Kind::FireFirst=>{let mut q=first::input();q.static_source_roofs=Some(false);Inputs::FireFirst(q)},
 Kind::FireAdvance=>{let mut q=fire_fixture::continuation(e.at,model.fire.queued_repeat);q.callback.static_source_roofs=Some(false);let mut bad=q.clone();bad.callback.scheduler_sample_ms=None;assert!(model.dispatch(b,b.observed,ticket,Inputs::FireAdvance(bad),&draw()).is_err());*refused+=1;Inputs::FireAdvance(q)},
 Kind::Roof(_)=>{let source=model.roof.next(b,b.observed).unwrap();let mut q=roof::TickInputs{timer_removed_before_callback:Some(true),callback_group_matches:Some(true),dispatch_ms:Some(e.at),fresh_schedule_samples:Some(vec![])};if let Err(err)=model.roof.prepare_tick(b,b.observed,&source,&q){assert!(err.to_string().contains("Missing source 4D65F0 fresh sample"),"{err}");q.fresh_schedule_samples=Some(vec![e.at]);}Inputs::Roof(q)},
 Kind::Locomotion(_)|Kind::IdleCycle(_)=>panic!("R458 finite attack recipe cannot dispatch continuation branches"),
 };assert_eq!(model.clock(b,b.observed).unwrap(),before);assert_eq!(model.next(b,b.observed).unwrap().event,e);let frame=model.dispatch(b,b.observed,ticket,input,&draw()).unwrap();assert!(model.dispatch(b,b.observed,ticket,Inputs::Player(fixture::inputs()),&draw()).is_err());if matches!(e.kind,Kind::PlayerStart|Kind::PlayerAdvance|Kind::PlayerIdle){let(bank,sub)=frame.player_frame.unwrap();player.push((e.at,bank,sub));}if matches!(e.kind,Kind::FireFirst|Kind::FireAdvance){fire.push((e.at,frame.fire_frame.unwrap()));}frame}
